package com.vibeguard.samples.newsletter; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*; import java.util.concurrent.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/newsletter") public class NewsletterController {private final Set<String> subscribers=ConcurrentHashMap.newKeySet();@PostMapping("/subscribe") public ResponseEntity<Void> subscribe(@Valid @RequestBody Request request){subscribers.add(request.email());return ResponseEntity.status(201).build();}@PostMapping("/unsubscribe") public ResponseEntity<Void> unsubscribe(@Valid @RequestBody Request request){subscribers.remove(request.email());return ResponseEntity.noContent().build();}@PostMapping("/campaigns") public Map<String,Object> campaign(@RequestBody Map<String,String> body){return Map.of("recipientCount",subscribers.size(),"status","QUEUED");}record Request(@Email String email){} }
